const { resolveTemplateSyncAction } = require('../theme-utils');

function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

function buildCollectionChanges(sourceCollection, destinationCollection) {
  const changes = {};

  if (sourceCollection.title !== destinationCollection.title) {
    changes.title = sourceCollection.title;
  }
  if (sourceCollection.descriptionHtml !== destinationCollection.descriptionHtml) {
    changes.descriptionHtml = sourceCollection.descriptionHtml;
  }
  if (sourceCollection.templateSuffix !== destinationCollection.templateSuffix) {
    changes.templateSuffix = sourceCollection.templateSuffix;
  }
  if (sourceCollection.sortOrder !== destinationCollection.sortOrder) {
    changes.sortOrder = sourceCollection.sortOrder;
  }
  if (
    JSON.stringify(sourceCollection.image) !== JSON.stringify(destinationCollection.image)
  ) {
    changes.image = sourceCollection.image
      ? {
          src: sourceCollection.image.url,
          altText: sourceCollection.image.altText
        }
      : null;
  }
  if (JSON.stringify(sourceCollection.seo) !== JSON.stringify(destinationCollection.seo)) {
    changes.seo = sourceCollection.seo
      ? {
          title: sourceCollection.seo.title,
          description: sourceCollection.seo.description
        }
      : undefined;
  }
  if (
    JSON.stringify(sourceCollection.ruleSet) !==
    JSON.stringify(destinationCollection.ruleSet)
  ) {
    changes.ruleSet = sourceCollection.ruleSet
      ? {
          appliedDisjunctively: sourceCollection.ruleSet.appliedDisjunctively,
          rules: sourceCollection.ruleSet.rules.map((rule) => ({
            column: rule.column,
            relation: rule.relation,
            condition: rule.condition
          }))
        }
      : null;
  }

  return changes;
}

async function syncCollections({ config, client }) {
  const result = makeResult();
  const sourceCollections = await client.source.collections.listAll();
  const destinationCollections = await client.destination.collections.listAll();

  const destinationByHandle = new Map(
    destinationCollections.map((collection) => [collection.handle, collection])
  );

  for (const sourceCollection of sourceCollections) {
    if (!sourceCollection.handle) {
      result.warnings.push(
        `Skipping source collection without handle (ID: ${sourceCollection.id}, Title: ${sourceCollection.title})`
      );
      continue;
    }

    const destinationCollection = destinationByHandle.get(sourceCollection.handle);
    const templateAction = await resolveTemplateSyncAction({
      objectType: 'collection',
      templateSuffix: sourceCollection.templateSuffix,
      config,
      client
    });
    result.warnings.push(...templateAction.warnings);

    if (templateAction.error) {
      result.errors.push(
        `Error processing collection "${sourceCollection.title}": ${templateAction.error}`
      );
      continue;
    }

    const preparedCollection = {
      ...sourceCollection,
      templateSuffix: templateAction.templateSuffix
    };

    if (!destinationCollection) {
      if (config.updateOnly) {
        continue;
      }

      try {
        const created = await client.destination.collections.create(preparedCollection);
        destinationByHandle.set(created.handle, created);
        result.created += 1;
      } catch (error) {
        result.errors.push(
          `Error creating collection "${sourceCollection.title}": ${error.message}`
        );
      }

      continue;
    }

    if (config.createOnly) {
      continue;
    }

    const changes = buildCollectionChanges(preparedCollection, destinationCollection);

    if (Object.keys(changes).length === 0) {
      continue;
    }

    try {
      await client.destination.collections.update(destinationCollection.id, changes);
      result.updated += 1;
    } catch (error) {
      result.errors.push(
        `Error updating collection "${sourceCollection.title}": ${error.message}`
      );
    }
  }

  if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
    const sourceHandles = new Set(
      sourceCollections.filter((collection) => collection.handle).map((collection) => collection.handle)
    );

    for (const destinationCollection of destinationCollections) {
      if (!destinationCollection.handle || sourceHandles.has(destinationCollection.handle)) {
        continue;
      }

      try {
        await client.destination.collections.delete(destinationCollection.id);
        result.deleted += 1;
      } catch (error) {
        result.errors.push(
          `Error deleting collection "${destinationCollection.title}": ${error.message}`
        );
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourceCollections.length,
    destinationCount: destinationCollections.length
  };

  return result;
}

module.exports = {
  syncCollections,
  buildCollectionChanges
};
